"use client";
/* Ducks, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Ducks(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("ducks"); }, []);
  return React.createElement("piix-pal", { "pal": "ducks", ...piixAttrs(props) });
}

export default Ducks;
